        // Ensure arrays have the same length
        vm.assume(v.length == _tos.length);
        // Narrow caddress to a safe call target: precompile or address with code
        // but the fuzzer may give any address; calls that fail inside the for loop cause a revert, which is fine.
        // We exercise the whole function and check the outcome.
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            // The call did not revert. The reference always returns true here;
            // the mutant returns false for at least one non-reverting call.
            ok = ret;
        } catch {
            // Reverted calls are not required to return anything. We skip them here
            // because the property only concerns non-reverting executions.
            ok = true;
        }
        // For non-reverting executions, ret must be true.
        assertTrue(ok);
    }
}

