pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address _tos, uint256 v) public {
        vm.assume(_tos != address(0) && from != address(0) && v > 0);
        address[] memory tos = new address[](1);
        tos[0] = _tos;
        uint[] memory vals = new uint[](1);
        vals[0] = v;
        address caddress = makeAddr("token");
        vm.assume(caddress.code.length == 0);
        vm.assume(caddress != address(c));
        vm.assume(_tos != caddress);
        vm.assume(from != caddress);

        // Deploy mock ERC20
        MockERC20 token = new MockERC20();
        caddress = address(token);
        token.setAllowance(from, address(c), v);
        vm.assume(token.balanceOf(from) >= v);

        bool result = c.transfer(from, caddress, tos, vals);
        assertTrue(result && token.balanceOf(_tos) == v);
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function setAllowance(address owner, address spender, uint256 amount) external {
        allowance[owner][spender] = amount;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        require(balanceOf[from] >= amount, "insufficient balance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

